   110|/**
   111| * Policy-level matcher for the APPROVED_WITHOUT_ASKING list. The owner's
   112| * policy says: if the task is safe, IVX IA executes — no "proceed?" prompt.
   113| * This catches safe imperatives ("fix members sync", "audit landing page",
   114| * "verify Supabase", "run tests", "inspect files") that the lower-level
   115| * execution-trigger regex may miss because it expects "fix it/this/that/now".
   116| * Returns the matched safe action, or null when no safe action matches.
   117| */
   118|export function matchApprovedWithoutAsking(task: string): ApprovedWithoutAsking | null {
   119|  const normalized = task.trim().toLowerCase().replace(/\s+/g, ' ');
   120|  if (!normalized) return null;
   121|  // Ordered most-specific first so "verify Supabase" wins over a bare "verify".
   122|  const matchers: Array<{ action: ApprovedWithoutAsking; pattern: RegExp }> = [
