   124|    { action: 'verify Render', pattern: /\b(render)\b.{0,40}\b(verify|check|inspect|status|health|deploy)\b|\b(verify|check|inspect|status|health)\b.{0,40}\b(render)\b/ },
   125|    { action: 'verify GitHub status', pattern: /\b(github)\b.{0,40}\b(verify|check|inspect|status|state|sync|push|repo)\b|\b(verify|check|inspect|status|state|sync)\b.{0,40}\b(github)\b/ },
