   142|export function resolveOwnerPolicyVerdict(
   143|  decision: IVXOwnerExecutionDecision,
   144|  task: string,
   145|): PolicyVerdict {
   146|  if (decision.requiresApproval) return 'ask_once';
   147|  if (decision.autoExecute) return 'auto_execute';
   148|  // The lower-level classifier may not flag a safe imperative as an execution
   149|  // command (it expects "fix it/this/that/now"). The owner's policy is explicit:
   150|  // safe actions on the APPROVED_WITHOUT_ASKING list execute automatically.
   151|  const safeMatch = matchApprovedWithoutAsking(task);
   152|  if (safeMatch) return 'auto_execute';
   153|  if (decision.isOwnerExecutionCommand) return 'auto_execute';
   154|  return 'route_normally';
